import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import * as React from 'react'

import type {Props} from './Sorter.types'

import styles from './Sorter.module.css'

const getItem = (name: string): SelectItem => ({
  key: name,
  label: name,
})

function Sorter({dimensions = [], descending, onChange, dimension}: Props) {
  const handleSelect = React.useCallback(
    (item: SelectItem | null) => {
      onChange(String(item?.key), descending)
    },
    [descending, onChange],
  )

  const handleCheck = React.useCallback(
    (e: React.SyntheticEvent<HTMLInputElement>) => {
      onChange(dimension, e.currentTarget.checked)
    },
    [dimension, onChange],
  )

  return (
    <>
      <label>
        {'Sort by '}
        <Select
          size={Select.Size.S}
          selected={getItem(dimension)}
          onChange={handleSelect}
          data={dimensions.map(getItem)}
        />
      </label>
      <Checkbox checked={descending} onChange={handleCheck} containerClassName={styles.checkbox}>
        {'in descending order'}
      </Checkbox>
    </>
  )
}

export default Sorter
